INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 10, 'theory', 'Quiz: CASE WHEN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 0, 'What does CASE return if no WHEN matched and there is no ELSE branch?', '["0", "An empty string", "NULL", "An error"]', 2, 'Without ELSE the result is NULL. That is why it is better to always write ELSE, even if it holds NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 1, 'The price is 500. Which label does CASE WHEN price < 10000 THEN ''mid'' WHEN price < 1000 THEN ''cheap'' END return?', '["cheap", "mid", "NULL", "An error"]', 1, 'Branches are checked top to bottom and the first match wins: 500 < 10000, so "mid". Conditions go from narrow to wide.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 2, 'How do you count paid orders with a conditional aggregate?', '["COUNT(status = ''paid'')", "SUM(CASE WHEN status = ''paid'' THEN 1 ELSE 0 END)", "CASE SUM(status) WHEN ''paid''", "COUNT(*) WHERE paid"]', 1, 'CASE returns 1 for matching rows and 0 for the rest; SUM adds up the ones. COUNT(expression) would count all non-empty values, zeros included.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 3, 'Why won''t a simple CASE x WHEN NULL … work on empty values?', '["NULL cannot be written in CASE", "Simple CASE compares with =, and NULL = NULL is not true", "x must be a number", "WHEN does not accept constants"]', 1, 'The simple form compares for equality, and a comparison with NULL gives UNKNOWN. For gaps you need the searched form with WHEN x IS NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 10, 4, 'How can CASE put statuses in life-cycle order?', '["ORDER BY CASE status WHEN ''new'' THEN 1 WHEN ''paid'' THEN 2 … END", "GROUP BY CASE", "WHERE CASE", "It is impossible"]', 0, 'CASE in ORDER BY maps values to numbers and the sorting goes by them — any order you need.');
